<x-hris.modal id="recognition-editor" title="Recognition event"><form id="recognition-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="name" required/><x-hris.field name="type" type="select" :options="['voting'=>'Voting','attendance'=>'Attendance']" required/><x-hris.field name="coverage_start" type="date" required/><x-hris.field name="coverage_end" type="date" required/><x-hris.field name="recognition_date" type="date" required/><x-hris.field name="opens_at" label="Voting opens (Manila)" type="datetime-local"/><x-hris.field name="closes_at" label="Voting closes (Manila)" type="datetime-local"/><div class="col-12"><label for="recognition-voter-types" class="form-label">Eligible voter employee types</label><select class="form-select" multiple id="recognition-voter-types" name="voter_types" required><option>Permanent</option><option>Contractual Regular</option><option>CSW</option></select></div><div class="col-12 form-check ms-2"><input id="recognition-self" class="form-check-input" type="checkbox" name="allow_self_vote"><label for="recognition-self" class="form-check-label">Allow self voting</label></div><x-hris.employee-picker name="nominee_ids" label="Nominees" multiple/></div><p class="form-text mt-3">One final ballot per eligible voter. Individual voter identities are private. HR can inspect aggregates; other employees see counts after voting closes. HR confirms winners separately.</p></div><div class="modal-footer"><button class="btn btn-primary">Save event</button></div></form></x-hris.modal>
