@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#recognition-table'),form=document.querySelector('#recognition-form'),publish=document.querySelector('#recognition-publish-form');if(form){HRIS.bindForm(form,{prepare:body=>{body.voter_types=[...form.elements.voter_types.selectedOptions].map(option=>option.value)},success:()=>table.table.load()});HRIS.bindForm(publish,{success:()=>table.table.load()});document.querySelector('#new-recognition').onclick=()=>{HRIS.fillForm(form,{});form.dataset.endpoint='/recognition';form.dataset.method='POST';HRIS.openModal('recognition-editor')}}table.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='details'){document.querySelector('#recognition-info').textContent=`${row.name} · ${row.results_state}`;const list=document.querySelector('#recognition-nominees');list.replaceChildren();for(const nominee of row.nominees){const item=document.createElement('div'),label=document.createElement('span');label.textContent=`${nominee.snapshot.name}${nominee.winner?' · Confirmed winner':''}${nominee.votes_count!==undefined?` · ${nominee.votes_count} votes`:''}`;item.append(label);if(row.can_vote){const button=document.createElement('button');button.className='btn btn-sm btn-outline-primary ms-2';button.textContent='Vote';button.onclick=async()=>{if(!await HRIS.confirm(`Submit your final ballot for ${nominee.snapshot.name}?`))return;button.disabled=true;try{HRIS.feedback((await HRIS.request(`/recognition/${row.id}/vote`,{method:'POST',body:{nominee_id:nominee.id}})).message);list.querySelectorAll('button').forEach(button=>button.disabled=true);table.table.load()}catch(error){button.disabled=false;HRIS.feedback(error.message,true)}};item.append(button)}list.append(item)}HRIS.openModal('recognition-details')}else if(action==='edit'){const picker=form.elements.nominee_ids;for(const nominee of row.nominees)if(![...picker.options].some(o=>o.value===String(nominee.user_id)))picker.append(new Option(nominee.snapshot.name,nominee.user_id));HRIS.fillForm(form,{...row,nominee_ids:row.nominees.map(n=>n.user_id),voter_types:[]});[...form.elements.voter_types.options].forEach(o=>o.selected=row.voter_types.includes(o.value));form.dataset.endpoint=`/recognition/${row.id}`;form.dataset.method='PUT';HRIS.openModal('recognition-editor')}else if(action==='publish'){const select=publish.elements.winner_ids;select.replaceChildren(...row.nominees.map(n=>new Option(n.snapshot.name,n.id)));publish.dataset.endpoint=`/recognition/${row.id}/publish`;HRIS.openModal('recognition-publish')}else if(await HRIS.confirm('Archive this event and preserve its ballots?')){HRIS.feedback((await HRIS.request(`/recognition/${row.id}/archive`,{method:'POST'})).message);table.table.load()}}catch(error){HRIS.feedback(error.message,true)}})});</script>@endpush
